	@Test
	void injectsOneExactBindingAtTheStartOfTheOuterWhereClause() throws Exception {
		String query = "SELECT ?s WHERE { ?s <urn:p> <urn:o> }";
		MapBindingSet initialBindings = binding("s", VF.createBNode("fixed"));
		String serialized = withInitialBindings(query, initialBindings);

		int where = serialized.toUpperCase(Locale.ROOT).indexOf("WHERE");
		int openBrace = serialized.indexOf('{', where);
		assertTrue(where >= 0 && openBrace > where);
		assertTrue(serialized.substring(openBrace + 1).stripLeading().startsWith("VALUES"), serialized);
		List<BindingSetAssignment> assignments = new ArrayList<>();
		parse(serialized).getTupleExpr().visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(BindingSetAssignment node) {
				assignments.add(node);
			}
		});
		assertEquals(1, assignments.size());
		Iterator<BindingSet> injectedBindings = assignments.get(0).getBindingSets().iterator();
		assertTrue(injectedBindings.hasNext());
		assertEquals(VF.createBNode("fixed"), injectedBindings.next().getValue("s"));
		assertFalse(injectedBindings.hasNext());

		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(VF.createBNode("fixed"), PREDICATE, OBJECT);
			List<BindingSet> rows = evaluate(connection, serialized);
			assertEquals(1, rows.size());
			assertEquals(VF.createBNode("fixed"), rows.get(0).getValue("s"));
		}
	}

	@Test
	void initialBnodeBindingWorksForSelectAskAndBound() throws Exception {
		BNode fixed = VF.createBNode("fixed");
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(fixed, PREDICATE, OBJECT);

			List<BindingSet> selectRows = evaluate(connection,
					withInitialBindings("SELECT ?s WHERE { ?s <urn:p> <urn:o> }", binding("s", fixed)));
			assertEquals(1, selectRows.size());
			assertEquals(fixed, selectRows.get(0).getValue("s"));

			String ask = withInitialBindings("ASK { ?s <urn:p> <urn:o> }", binding("s", fixed));
			assertTrue(connection.prepareBooleanQuery(ask).evaluate());

			List<BindingSet> boundRows = evaluate(connection, withInitialBindings(
					"SELECT ?bound WHERE { BIND(BOUND(?b) AS ?bound) }", binding("b", fixed)));
			assertEquals(1, boundRows.size());
			assertEquals(VF.createLiteral(true), boundRows.get(0).getValue("bound"));
		}
	}

	@Test
	void predicateVariableRemainsVariableWhenItsInitialBindingIsAnIri() throws Exception {
		IRI otherPredicate = VF.createIRI("urn:q");
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(VF.createBNode("selected"), PREDICATE, OBJECT);
			connection.add(VF.createBNode("other"), otherPredicate, OBJECT);
			String serialized = withInitialBindings("SELECT ?s ?p WHERE { ?s ?p ?o }", binding("p", PREDICATE));
			List<StatementPattern> patterns = new ArrayList<>();
			parse(serialized).getTupleExpr().visit(new AbstractQueryModelVisitor<RuntimeException>() {
				@Override
				public void meet(StatementPattern node) {
					patterns.add(node);
				}
			});
			assertEquals(1, patterns.size());
			assertEquals("p", patterns.get(0).getPredicateVar().getName());
			assertFalse(patterns.get(0).getPredicateVar().hasValue());

			List<BindingSet> rows = evaluate(connection, serialized);
			assertEquals(1, rows.size());
			assertEquals(VF.createBNode("selected"), rows.get(0).getValue("s"));
			assertEquals(PREDICATE, rows.get(0).getValue("p"));
		}
	}

